window.CURATED_EXAMPLES=(window.CURATED_EXAMPLES||[]).concat([{"id":"curatedF0","title":"Rainbow Prism","category":"Science","desc":"A white beam splits into seven colored rays through a prism","code":"speed(0)\nhideturtle()\ndef disc(x,y,r,c):\n    penup()\n    goto(x,y)\n    dot(2*r,c)\ndef path(points,c,w=3):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    pensize(w)\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    penup()\ndef fill(points,c):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    begin_fill()\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    goto(points[0][0],points[0][1])\n    end_fill()\n    penup()\ndef rect(x,y,w,h,c):\n    fill([(x,y),(x+w,y),(x+w,y+h),(x,y+h)],c)\nbgcolor(\"#13273c\")\npath([(-186,37),(-49,9)],\"#eff3e8\",7)\nfill([(-49,-93),(35,71),(121,-93)],\"#7694a1\")\nfill([(-35,-69),(35,55),(102,-69)],\"#b3ced2\")\ncolors=[\"#ed7981\",\"#f0a46d\",\"#f1cf73\",\"#9dc487\",\"#65b5ae\",\"#719cca\",\"#ac91c1\"]\nfor n,c in enumerate(colors):\n    path([(35,1),(187,83-n*25)],c,5)\nfor x,y in [(-153,144),(-68,146),(103,137)]:\n    disc(x,y,4,\"#e7e6d6\")\nhideturtle()","art":"curated"},{"id":"curatedF1","title":"Light Refraction","category":"Science","desc":"A ray bends while crossing a clear glass block","code":"speed(0)\nhideturtle()\ndef disc(x,y,r,c):\n    penup()\n    goto(x,y)\n    dot(2*r,c)\ndef path(points,c,w=3):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    pensize(w)\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    penup()\ndef fill(points,c):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    begin_fill()\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    goto(points[0][0],points[0][1])\n    end_fill()\n    penup()\ndef rect(x,y,w,h,c):\n    fill([(x,y),(x+w,y),(x+w,y+h),(x,y+h)],c)\nbgcolor(\"#edf1eb\")\nfill([(-95,102),(87,102),(87,-102),(-95,-102)],\"#bfdfe4\")\npath([(-170,158),(-95,65),(87,-39),(167,-131)],\"#d98d70\",5)\npath([(-95,65),(-95,-102)],\"#719ca8\",2)\npath([(87,-39),(87,102)],\"#719ca8\",2)\nfor x,y in [(-95,65),(87,-39)]:\n    disc(x,y,9,\"#e5b272\")\npenup()\ngoto(0,145)\ncolor(\"#486a73\")\nwrite(\"GLASS\",align=\"center\",font=(\"Arial\",17,\"bold\"))\nhideturtle()","art":"curated"},{"id":"curatedF2","title":"Newton's Cradle","category":"Science","desc":"Five suspended metal balls transferring momentum","code":"speed(0)\nhideturtle()\ndef disc(x,y,r,c):\n    penup()\n    goto(x,y)\n    dot(2*r,c)\ndef path(points,c,w=3):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    pensize(w)\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    penup()\ndef fill(points,c):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    begin_fill()\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    goto(points[0][0],points[0][1])\n    end_fill()\n    penup()\ndef rect(x,y,w,h,c):\n    fill([(x,y),(x+w,y),(x+w,y+h),(x,y+h)],c)\nbgcolor(\"#e6eae5\")\npath([(-159,144),(159,144)],\"#657f83\",11)\nfor n in range(5):\n    x=-88+n*44\n    xx=x if n else x-64\n    yy=-37 if n else -14\n    path([(x,142),(xx,yy+21)],\"#728e90\",2)\n    disc(xx,yy,22,\"#a4b8b9\")\n    disc(xx-6,yy+7,7,\"#dce6e2\")\nfor x in [-148,148]:\n    path([(x,142),(x,-158)],\"#87999b\",7)\npath([(-166,-158),(166,-158)],\"#87999b\",9)\nhideturtle()","art":"curated"},{"id":"curatedF3","title":"Double Pendulum","category":"Science","desc":"Two pendulums overlaid with a long traced path","code":"speed(0)\nhideturtle()\ndef disc(x,y,r,c):\n    penup()\n    goto(x,y)\n    dot(2*r,c)\ndef path(points,c,w=3):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    pensize(w)\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    penup()\ndef fill(points,c):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    begin_fill()\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    goto(points[0][0],points[0][1])\n    end_fill()\n    penup()\ndef rect(x,y,w,h,c):\n    fill([(x,y),(x+w,y),(x+w,y+h),(x,y+h)],c)\nimport math\nbgcolor(\"#1d3040\")\ndisc(0,121,15,\"#c5ab7e\")\npath([(0,121),(-85,39),(38,-67)],\"#849b9f\",6)\ndisc(-85,39,21,\"#d2aa7c\")\ndisc(38,-67,23,\"#96b7b7\")\npenup()\nfor n in range(1200):\n    t=n*.025\n    x=math.sin(t*1.22)*92+math.sin(t*2.19)*43\n    y=math.cos(t*1.22)*67+math.sin(t*1.71)*56-35\n    color(\"#6fc6c0\" if n%3 else \"#e3b872\")\n    goto(x,y)\n    pendown()\nhideturtle()","art":"curated"},{"id":"curatedF4","title":"Coordinate Grid","category":"Math","desc":"Axes, units and four colored plotted points","code":"speed(0)\nhideturtle()\ndef disc(x,y,r,c):\n    penup()\n    goto(x,y)\n    dot(2*r,c)\ndef path(points,c,w=3):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    pensize(w)\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    penup()\ndef fill(points,c):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    begin_fill()\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    goto(points[0][0],points[0][1])\n    end_fill()\n    penup()\ndef rect(x,y,w,h,c):\n    fill([(x,y),(x+w,y),(x+w,y+h),(x,y+h)],c)\nbgcolor(\"#faf8ef\")\nfor x in range(-160,161,40):\n    path([(x,-180),(x,180)],\"#dfdfd5\",1)\nfor y in range(-160,161,40):\n    path([(-180,y),(180,y)],\"#dfdfd5\",1)\npath([(-185,0),(185,0)],\"#587a83\",3)\npath([(0,-185),(0,185)],\"#587a83\",3)\nfor x,y,c,name in [(-120,80,\"#d88170\",\"A\"),(120,120,\"#739cac\",\"B\"),\n                    (-80,-120,\"#bc9bc7\",\"C\"),(80,-40,\"#93ad7f\",\"D\")]:\n    disc(x,y,10,c)\n    penup()\n    goto(x+16,y+9)\n    color(c)\n    write(name,font=(\"Arial\",15,\"bold\"))\nhideturtle()","art":"curated"},{"id":"curatedF5","title":"Scatter Plot","category":"Science","desc":"A scattered relationship with a fitted trend line","code":"speed(0)\nhideturtle()\ndef disc(x,y,r,c):\n    penup()\n    goto(x,y)\n    dot(2*r,c)\ndef path(points,c,w=3):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    pensize(w)\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    penup()\ndef fill(points,c):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    begin_fill()\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    goto(points[0][0],points[0][1])\n    end_fill()\n    penup()\ndef rect(x,y,w,h,c):\n    fill([(x,y),(x+w,y),(x+w,y+h),(x,y+h)],c)\nimport random\nrandom.seed(34)\nbgcolor(\"#f7f3e9\")\npath([(-164,-145),(172,-145)],\"#677f80\",4)\npath([(-164,-145),(-164,164)],\"#677f80\",4)\nfor n in range(41):\n    x=-143+n*8\n    y=-87+n*5+random.randint(-37,37)\n    disc(x,y,5,\"#5d9aa4\" if n%2 else \"#c98e72\")\npath([(-147,-102),(166,100)],\"#cfab68\",4)\npenup()\ngoto(0,169)\ncolor(\"#415d65\")\nwrite(\"SCATTER PLOT\",align=\"center\",font=(\"Arial\",16,\"bold\"))\nhideturtle()","art":"curated"},{"id":"curatedF6","title":"Bubble Chart","category":"Science","desc":"A multivariate bubble chart with varied circles","code":"speed(0)\nhideturtle()\ndef disc(x,y,r,c):\n    penup()\n    goto(x,y)\n    dot(2*r,c)\ndef path(points,c,w=3):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    pensize(w)\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    penup()\ndef fill(points,c):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    begin_fill()\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    goto(points[0][0],points[0][1])\n    end_fill()\n    penup()\ndef rect(x,y,w,h,c):\n    fill([(x,y),(x+w,y),(x+w,y+h),(x,y+h)],c)\nbgcolor(\"#f7f4eb\")\npath([(-165,-138),(169,-138)],\"#6c8484\",3)\npath([(-165,-138),(-165,160)],\"#6c8484\",3)\ndots=[(-112,-67,27,\"#d79a85\"),(-78,24,12,\"#d9be79\"),\n      (-24,-36,41,\"#7bad9e\"),(6,91,18,\"#a4a0cc\"),\n      (67,12,32,\"#89a9c6\"),(124,93,17,\"#c491ad\")]\nfor x,y,r,c in dots:\n    disc(x,y,r,c)\n    disc(x,y,5,\"#f8f4eb\")\nhideturtle()","art":"curated"},{"id":"curatedF7","title":"Stacked Bar Chart","category":"Science","desc":"Stacked bars showing category contributions","code":"speed(0)\nhideturtle()\ndef disc(x,y,r,c):\n    penup()\n    goto(x,y)\n    dot(2*r,c)\ndef path(points,c,w=3):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    pensize(w)\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    penup()\ndef fill(points,c):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    begin_fill()\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    goto(points[0][0],points[0][1])\n    end_fill()\n    penup()\ndef rect(x,y,w,h,c):\n    fill([(x,y),(x+w,y),(x+w,y+h),(x,y+h)],c)\nbgcolor(\"#f8f5ec\")\ndata=[[47,61,31],[63,29,72],[41,77,41],[81,44,39],[61,58,64]]\ncolors=[\"#6fa5a4\",\"#df9a7d\",\"#cab37b\"]\npath([(-164,-124),(171,-124)],\"#647f80\",3)\nfor n,segments in enumerate(data):\n    x=-146+n*68\n    y=-123\n    for k,height in enumerate(segments):\n        rect(x,y,46,height,colors[k])\n        y+=height\nfor n in range(5):\n    penup()\n    goto(-124+n*68,-153)\n    color(\"#425f63\")\n    write(str(n+1),align=\"center\",font=(\"Arial\",14))\nhideturtle()","art":"curated"},{"id":"curatedF8","title":"Line Graph","category":"Science","desc":"Three changing series with data-point markers","code":"speed(0)\nhideturtle()\ndef disc(x,y,r,c):\n    penup()\n    goto(x,y)\n    dot(2*r,c)\ndef path(points,c,w=3):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    pensize(w)\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    penup()\ndef fill(points,c):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    begin_fill()\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    goto(points[0][0],points[0][1])\n    end_fill()\n    penup()\ndef rect(x,y,w,h,c):\n    fill([(x,y),(x+w,y),(x+w,y+h),(x,y+h)],c)\nbgcolor(\"#f7f4eb\")\npath([(-168,-135),(173,-135)],\"#708687\",3)\npath([(-168,-135),(-168,164)],\"#708687\",3)\nlines=[\n ([-91,-54,23,10,71,90],\"#559d9d\"),\n ([-6,44,-12,74,33,109],\"#c88278\"),\n ([-81,-27,-61,21,-19,48],\"#b7a06f\")]\nfor values,shade in lines:\n    pts=[]\n    for k,value in enumerate(values):\n        x=-139+k*56\n        pts.append((x,value))\n        disc(x,value,6,shade)\n    path(pts,shade,3)\nhideturtle()","art":"curated"},{"id":"curatedF9","title":"Area Chart","category":"Science","desc":"Filled data area beneath a changing curve","code":"speed(0)\nhideturtle()\ndef disc(x,y,r,c):\n    penup()\n    goto(x,y)\n    dot(2*r,c)\ndef path(points,c,w=3):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    pensize(w)\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    penup()\ndef fill(points,c):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    begin_fill()\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    goto(points[0][0],points[0][1])\n    end_fill()\n    penup()\ndef rect(x,y,w,h,c):\n    fill([(x,y),(x+w,y),(x+w,y+h),(x,y+h)],c)\nbgcolor(\"#f4f5eb\")\nvalues=[-78,-32,-49,18,7,71,38,118]\npoints=[(-156+i*44,values[i]) for i in range(len(values))]\nfill([(-156,-124)]+points+[(152,-124)],\"#88bdb5\")\npath(points,\"#408e91\",5)\npath([(-161,-124),(173,-124)],\"#657a79\",3)\nfor x,y in points:\n    disc(x,y,5,\"#3b8490\")\nhideturtle()","art":"curated"},{"id":"curatedF10","title":"Color Heatmap","category":"Science","desc":"A grid of temperature-like numerical values","code":"speed(0)\nhideturtle()\ndef disc(x,y,r,c):\n    penup()\n    goto(x,y)\n    dot(2*r,c)\ndef path(points,c,w=3):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    pensize(w)\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    penup()\ndef fill(points,c):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    begin_fill()\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    goto(points[0][0],points[0][1])\n    end_fill()\n    penup()\ndef rect(x,y,w,h,c):\n    fill([(x,y),(x+w,y),(x+w,y+h),(x,y+h)],c)\nimport math\nbgcolor(\"#f4f2e8\")\ncolors=[\"#3e7c9c\",\"#73a8b2\",\"#a7c5b1\",\"#d8c189\",\"#db936f\",\"#ba655c\"]\nfor row in range(12):\n    for col in range(12):\n        value=math.sin(row*.6)+math.cos(col*.7)+math.sin((row+col)*.4)\n        level=max(0,min(5,int((value+2.6)/5.2*6)))\n        rect(-174+col*29,148-row*29,27,27,colors[level])\nhideturtle()","art":"curated"},{"id":"curatedF11","title":"Decision Tree","category":"Science","desc":"A decision diagram splitting into four outcomes","code":"speed(0)\nhideturtle()\ndef disc(x,y,r,c):\n    penup()\n    goto(x,y)\n    dot(2*r,c)\ndef path(points,c,w=3):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    pensize(w)\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    penup()\ndef fill(points,c):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    begin_fill()\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    goto(points[0][0],points[0][1])\n    end_fill()\n    penup()\ndef rect(x,y,w,h,c):\n    fill([(x,y),(x+w,y),(x+w,y+h),(x,y+h)],c)\nbgcolor(\"#f4f4eb\")\nrect(-69,111,138,45,\"#5f91a1\")\npath([(0,110),(0,69),(-92,41)],\"#6a8080\",4)\npath([(0,69),(92,41)],\"#6a8080\",4)\nfor x,c in [(-92,\"#d6a579\"),(92,\"#9dae85\")]:\n    disc(x,13,41,c)\n    path([(x,-29),(x,-75),(x-47,-111)],\"#6a8080\",3)\n    path([(x,-75),(x+47,-111)],\"#6a8080\",3)\n    for xx in [x-47,x+47]:\n        disc(xx,-126,20,\"#b1c0bd\")\npenup()\ngoto(0,127)\ncolor(\"#f5f7ef\")\nwrite(\"START\",align=\"center\",font=(\"Arial\",14,\"bold\"))\nhideturtle()","art":"curated"},{"id":"curatedF12","title":"Program Flowchart","category":"Science","desc":"A visual program loop with a condition diamond","code":"speed(0)\nhideturtle()\ndef disc(x,y,r,c):\n    penup()\n    goto(x,y)\n    dot(2*r,c)\ndef path(points,c,w=3):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    pensize(w)\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    penup()\ndef fill(points,c):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    begin_fill()\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    goto(points[0][0],points[0][1])\n    end_fill()\n    penup()\ndef rect(x,y,w,h,c):\n    fill([(x,y),(x+w,y),(x+w,y+h),(x,y+h)],c)\nbgcolor(\"#f5f1e7\")\nrect(-71,109,142,54,\"#8ab6ab\")\nfill([(0,73),(101,8),(0,-55),(-101,8)],\"#e6c188\")\nrect(-65,-158,130,47,\"#7da4bd\")\npath([(0,109),(0,74)],\"#6c8284\",4)\npath([(0,-55),(0,-110)],\"#6c8284\",4)\npath([(101,8),(151,8),(151,136),(72,136)],\"#6c8284\",4)\nfor y,msg in [(129,\"START\"),(6,\"i < 10?\"),(-142,\"PRINT\")]:\n    penup()\n    goto(0,y-6)\n    color(\"#30484f\")\n    write(msg,align=\"center\",font=(\"Arial\",16,\"bold\"))\nhideturtle()","art":"curated"},{"id":"curatedF13","title":"Social Network Graph","category":"Science","desc":"Connected community nodes and several central hubs","code":"speed(0)\nhideturtle()\ndef disc(x,y,r,c):\n    penup()\n    goto(x,y)\n    dot(2*r,c)\ndef path(points,c,w=3):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    pensize(w)\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    penup()\ndef fill(points,c):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    begin_fill()\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    goto(points[0][0],points[0][1])\n    end_fill()\n    penup()\ndef rect(x,y,w,h,c):\n    fill([(x,y),(x+w,y),(x+w,y+h),(x,y+h)],c)\nimport math\nbgcolor(\"#172d3e\")\npoints=[]\nfor i in range(15):\n    a=i*2*math.pi/15\n    points.append((math.cos(a)*139,math.sin(a)*139))\nfor i in range(15):\n    for step in [1,4,7]:\n        path([points[i],points[(i+step)%15]],\"#496978\",1)\nfor i,(x,y) in enumerate(points):\n    disc(x,y,12,\"#ddae77\" if i%3==0 else \"#7fadb9\")\ndisc(0,0,23,\"#e0ce98\")\nfor i in range(0,15,3):\n    path([(0,0),points[i]],\"#698e97\",2)\nhideturtle()","art":"curated"},{"id":"curatedF14","title":"Binary Switchboard","category":"Science","desc":"Eight illuminated switches spelling a binary byte","code":"speed(0)\nhideturtle()\ndef disc(x,y,r,c):\n    penup()\n    goto(x,y)\n    dot(2*r,c)\ndef path(points,c,w=3):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    pensize(w)\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    penup()\ndef fill(points,c):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    begin_fill()\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    goto(points[0][0],points[0][1])\n    end_fill()\n    penup()\ndef rect(x,y,w,h,c):\n    fill([(x,y),(x+w,y),(x+w,y+h),(x,y+h)],c)\nbgcolor(\"#1c343c\")\nbits=[1,0,1,1,0,0,1,0]\nfor i,bit in enumerate(bits):\n    x=-154+i*44\n    rect(x,-48,35,112,\"#435b62\")\n    disc(x+17,18,13,\"#68ccb1\" if bit else \"#5e7477\")\n    rect(x+10,-30 if bit else -10,14,28,\"#b8cbc4\")\n    penup()\n    goto(x+17,-86)\n    color(\"#d1e3dd\")\n    write(str(2**(7-i)),align=\"center\",font=(\"Arial\",11))\npenup()\ngoto(0,114)\ncolor(\"#f0cc83\")\nwrite(\"10110010\",align=\"center\",font=(\"Courier\",29,\"bold\"))\nhideturtle()","art":"curated"},{"id":"curatedF15","title":"AND Logic Gate","category":"Science","desc":"An electronic AND gate with two inputs and an output","code":"speed(0)\nhideturtle()\ndef disc(x,y,r,c):\n    penup()\n    goto(x,y)\n    dot(2*r,c)\ndef path(points,c,w=3):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    pensize(w)\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    penup()\ndef fill(points,c):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    begin_fill()\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    goto(points[0][0],points[0][1])\n    end_fill()\n    penup()\ndef rect(x,y,w,h,c):\n    fill([(x,y),(x+w,y),(x+w,y+h),(x,y+h)],c)\nbgcolor(\"#edf2eb\")\npath([(-181,67),(-66,67)],\"#608e9d\",5)\npath([(-181,-67),(-66,-67)],\"#608e9d\",5)\nfill([(-65,-111),(0,-111),(79,-63),(105,0),\n      (79,63),(0,111),(-65,111)],\"#7eb4b6\")\nrect(-65,-111,53,222,\"#7eb4b6\")\npath([(102,0),(181,0)],\"#608e9d\",5)\nfor x,y,msg in [(-158,87,\"A\"),(-158,-47,\"B\"),(145,18,\"Q\")]:\n    penup()\n    goto(x,y)\n    color(\"#385964\")\n    write(msg,font=(\"Arial\",18,\"bold\"))\nhideturtle()","art":"curated"},{"id":"curatedF16","title":"OR Logic Gate","category":"Science","desc":"An electronic OR gate with curved input side","code":"speed(0)\nhideturtle()\ndef disc(x,y,r,c):\n    penup()\n    goto(x,y)\n    dot(2*r,c)\ndef path(points,c,w=3):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    pensize(w)\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    penup()\ndef fill(points,c):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    begin_fill()\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    goto(points[0][0],points[0][1])\n    end_fill()\n    penup()\ndef rect(x,y,w,h,c):\n    fill([(x,y),(x+w,y),(x+w,y+h),(x,y+h)],c)\nbgcolor(\"#edf1e9\")\npath([(-181,67),(-64,67)],\"#628d99\",5)\npath([(-181,-67),(-64,-67)],\"#628d99\",5)\nfill([(-66,-111),(44,-111),(126,0),(44,111),(-66,111),(-12,0)],\"#8fb7b2\")\npath([(-67,-111),(-12,0),(-67,111)],\"#668d92\",6)\npath([(126,0),(183,0)],\"#628d99\",5)\nfor x,y,msg in [(-154,86,\"A\"),(-154,-46,\"B\"),(149,18,\"Q\")]:\n    penup()\n    goto(x,y)\n    color(\"#385964\")\n    write(msg,font=(\"Arial\",18,\"bold\"))\nhideturtle()","art":"curated"},{"id":"curatedF17","title":"Seven Segment Display","category":"Science","desc":"Four digital numerals built from line segments","code":"speed(0)\nhideturtle()\ndef disc(x,y,r,c):\n    penup()\n    goto(x,y)\n    dot(2*r,c)\ndef path(points,c,w=3):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    pensize(w)\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    penup()\ndef fill(points,c):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    begin_fill()\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    goto(points[0][0],points[0][1])\n    end_fill()\n    penup()\ndef rect(x,y,w,h,c):\n    fill([(x,y),(x+w,y),(x+w,y+h),(x,y+h)],c)\nbgcolor(\"#162d36\")\ndigits=[[1,1,1,1,1,1,0],[0,1,1,0,0,0,0],\n        [1,1,0,1,1,0,1],[1,1,1,1,0,0,1]]\nsegments=[((-18,44),(18,44)),((24,38),(24,2)),((24,-5),(24,-41)),\n          ((-18,-45),(18,-45)),((-24,-5),(-24,-41)),\n          ((-24,38),(-24,2)),((-18,0),(18,0))]\nfor n,pattern in enumerate(digits):\n    cx=-120+n*81\n    for index,on in enumerate(pattern):\n        a,b=segments[index]\n        path([(cx+a[0],a[1]),(cx+b[0],b[1])],\n             \"#eaa76d\" if on else \"#334a50\",8)\nfor x in [-160,160]:\n    disc(x,-147,6,\"#96b3b3\")\nhideturtle()","art":"curated"},{"id":"curatedF18","title":"Morse Code SOS","category":"Science","desc":"Nine Morse signals illustrated as dots and dashes","code":"speed(0)\nhideturtle()\ndef disc(x,y,r,c):\n    penup()\n    goto(x,y)\n    dot(2*r,c)\ndef path(points,c,w=3):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    pensize(w)\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    penup()\ndef fill(points,c):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    begin_fill()\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    goto(points[0][0],points[0][1])\n    end_fill()\n    penup()\ndef rect(x,y,w,h,c):\n    fill([(x,y),(x+w,y),(x+w,y+h),(x,y+h)],c)\nbgcolor(\"#17313b\")\nletters=[[\".\",\".\",\".\"] ,[\"-\",\"-\",\"-\"],[\".\",\".\",\".\"]]\nfor row,signals in enumerate(letters):\n    y=100-row*98\n    for col,symbol in enumerate(signals):\n        x=-118+col*117\n        if symbol==\".\":\n            disc(x,y,17,\"#ebc781\")\n        else:\n            path([(x-30,y),(x+30,y)],\"#ebc781\",14)\n    penup()\n    goto(0,y-37)\n    color(\"#b3d8d2\")\n    write([\"S\",\"O\",\"S\"][row],align=\"center\",font=(\"Arial\",18,\"bold\"))\nhideturtle()","art":"curated"},{"id":"curatedF19","title":"Pixel Gradient","category":"Pixel Art","desc":"A pixel field with a smooth color transition","code":"speed(0)\nhideturtle()\ndef disc(x,y,r,c):\n    penup()\n    goto(x,y)\n    dot(2*r,c)\ndef path(points,c,w=3):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    pensize(w)\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    penup()\ndef fill(points,c):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    begin_fill()\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    goto(points[0][0],points[0][1])\n    end_fill()\n    penup()\ndef rect(x,y,w,h,c):\n    fill([(x,y),(x+w,y),(x+w,y+h),(x,y+h)],c)\nbgcolor(\"#f4f2ec\")\npalette=[\"#314f73\",\"#3b7193\",\"#5195ad\",\"#70b4bd\",\n         \"#a2c7ae\",\"#d1cc93\",\"#eebc88\",\"#db8d78\"]\nfor row in range(14):\n    for col in range(14):\n        index=max(0,min(7,(col+row)//4))\n        rect(-168+col*24,168-row*24,23,23,palette[index])\nhideturtle()","art":"curated"},{"id":"curatedF20","title":"Halftone Sphere","category":"Art","desc":"A sphere shaded with variable-size printed dots","code":"speed(0)\nhideturtle()\ndef disc(x,y,r,c):\n    penup()\n    goto(x,y)\n    dot(2*r,c)\ndef path(points,c,w=3):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    pensize(w)\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    penup()\ndef fill(points,c):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    begin_fill()\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    goto(points[0][0],points[0][1])\n    end_fill()\n    penup()\ndef rect(x,y,w,h,c):\n    fill([(x,y),(x+w,y),(x+w,y+h),(x,y+h)],c)\nimport math\nbgcolor(\"#f4eee2\")\nfor y in range(-139,140,13):\n    for x in range(-139,140,13):\n        r=math.sqrt(x*x+y*y)\n        if r<139:\n            light=(x-y)/278\n            size=max(1,7+(r/139)*2-light*7)\n            disc(x,y,size,\"#416f77\")\nhideturtle()","art":"curated"},{"id":"curatedF21","title":"Stippled Sunrise","category":"Art","desc":"A dawn landscape built from hundreds of colored points","code":"speed(0)\nhideturtle()\ndef disc(x,y,r,c):\n    penup()\n    goto(x,y)\n    dot(2*r,c)\ndef path(points,c,w=3):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    pensize(w)\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    penup()\ndef fill(points,c):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    begin_fill()\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    goto(points[0][0],points[0][1])\n    end_fill()\n    penup()\ndef rect(x,y,w,h,c):\n    fill([(x,y),(x+w,y),(x+w,y+h),(x,y+h)],c)\nimport random\nrandom.seed(22)\nbgcolor(\"#efd6b4\")\ndisc(62,74,58,\"#f6e1a1\")\nfor n in range(700):\n    x=random.uniform(-195,195)\n    y=random.uniform(-180,10)\n    shade=\"#8ca48c\" if y>-52 else \"#576f76\" if y>-107 else \"#364f63\"\n    disc(x,y,random.uniform(2,8),shade)\nfor x in [-125,-67,36,145]:\n    path([(x,-173),(x,-116)],\"#465f64\",4)\nhideturtle()","art":"curated"},{"id":"curatedF22","title":"Topographic Map","category":"Science","desc":"Nested elevation contours of a fictional mountain","code":"speed(0)\nhideturtle()\ndef disc(x,y,r,c):\n    penup()\n    goto(x,y)\n    dot(2*r,c)\ndef path(points,c,w=3):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    pensize(w)\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    penup()\ndef fill(points,c):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    begin_fill()\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    goto(points[0][0],points[0][1])\n    end_fill()\n    penup()\ndef rect(x,y,w,h,c):\n    fill([(x,y),(x+w,y),(x+w,y+h),(x,y+h)],c)\nimport math\nbgcolor(\"#f3f0e4\")\ncolors=[\"#9fc2af\",\"#89ae9b\",\"#729b88\",\"#648874\",\"#507b68\"]\nfor ring in range(13):\n    penup()\n    color(colors[(ring//3)%5])\n    pensize(2)\n    for n in range(360):\n        t=2*math.pi*n/359\n        r=151-ring*10+6*math.sin(5*t+ring*.3)+3*math.cos(9*t)\n        x=16+r*math.cos(t)\n        y=-7+r*.77*math.sin(t)\n        goto(x,y)\n        pendown()\nhideturtle()","art":"curated"},{"id":"curatedF23","title":"Contour Mountains","category":"Art","desc":"Multiple flowing contours resembling ridgelines","code":"speed(0)\nhideturtle()\ndef disc(x,y,r,c):\n    penup()\n    goto(x,y)\n    dot(2*r,c)\ndef path(points,c,w=3):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    pensize(w)\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    penup()\ndef fill(points,c):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    begin_fill()\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    goto(points[0][0],points[0][1])\n    end_fill()\n    penup()\ndef rect(x,y,w,h,c):\n    fill([(x,y),(x+w,y),(x+w,y+h),(x,y+h)],c)\nimport math\nbgcolor(\"#edece4\")\nfor row in range(14):\n    penup()\n    color([\"#536e7b\",\"#70939a\",\"#95b3ae\",\"#c6baa1\"][row%4])\n    pensize(2)\n    for x in range(-193,194,3):\n        y=-157+row*25+math.sin(x/35+row*.32)*17+math.sin(x/11+row)*5\n        goto(x,y)\n        pendown()\nhideturtle()","art":"curated"},{"id":"curatedF24","title":"Fractal Coastline","category":"Math","desc":"A jagged coastline generated by midpoint displacement","code":"speed(0)\nhideturtle()\ndef disc(x,y,r,c):\n    penup()\n    goto(x,y)\n    dot(2*r,c)\ndef path(points,c,w=3):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    pensize(w)\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    penup()\ndef fill(points,c):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    begin_fill()\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    goto(points[0][0],points[0][1])\n    end_fill()\n    penup()\ndef rect(x,y,w,h,c):\n    fill([(x,y),(x+w,y),(x+w,y+h),(x,y+h)],c)\nimport random\nrandom.seed(13)\nbgcolor(\"#dcece9\")\npts=[(-190,0),(190,0)]\nfor level in range(7):\n    nextpts=[]\n    for i in range(len(pts)-1):\n        a=pts[i]\n        b=pts[i+1]\n        offset=random.uniform(-100,100)/(level+1)**1.5\n        mid=((a[0]+b[0])/2,(a[1]+b[1])/2+offset)\n        nextpts.extend([a,mid])\n    nextpts.append(pts[-1])\n    pts=nextpts\nfill([(-200,-200)]+pts+[(200,-200)],\"#74a6b3\")\npath(pts,\"#3f7b86\",3)\nhideturtle()","art":"curated"},{"id":"curatedF25","title":"Dragon Curve","category":"Math","desc":"A paper-folding fractal path","code":"speed(0)\nhideturtle()\ndef disc(x,y,r,c):\n    penup()\n    goto(x,y)\n    dot(2*r,c)\ndef path(points,c,w=3):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    pensize(w)\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    penup()\ndef fill(points,c):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    begin_fill()\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    goto(points[0][0],points[0][1])\n    end_fill()\n    penup()\ndef rect(x,y,w,h,c):\n    fill([(x,y),(x+w,y),(x+w,y+h),(x,y+h)],c)\nbgcolor(\"#faf5ed\")\nimport math\nturns=[1]\nfor depth in range(11):\n    turns=turns+[1]+[-t for t in reversed(turns)]\nsetheading(0)\npenup()\ngoto(-51,-38)\npendown()\ncolor(\"#3f9097\")\npensize(2)\nfor turn in turns[:1600]:\n    forward(6)\n    right(90*turn)\nhideturtle()","art":"curated"},{"id":"curatedF26","title":"Cantor Dust","category":"Math","desc":"Fractal bars with the middle third removed repeatedly","code":"speed(0)\nhideturtle()\ndef disc(x,y,r,c):\n    penup()\n    goto(x,y)\n    dot(2*r,c)\ndef path(points,c,w=3):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    pensize(w)\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    penup()\ndef fill(points,c):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    begin_fill()\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    goto(points[0][0],points[0][1])\n    end_fill()\n    penup()\ndef rect(x,y,w,h,c):\n    fill([(x,y),(x+w,y),(x+w,y+h),(x,y+h)],c)\nbgcolor(\"#f5f0e5\")\ndef cantor(x,y,length,depth):\n    rect(x,y,length,15,\"#6e9b98\" if depth%2 else \"#bc9375\")\n    if depth==0:\n        return\n    cantor(x,y-38,length/3,depth-1)\n    cantor(x+length*2/3,y-38,length/3,depth-1)\ncantor(-175,145,350,5)\nhideturtle()","art":"curated"},{"id":"curatedF27","title":"Sierpinski Carpet","category":"Math","desc":"A self-similar carpet of repeating square cutouts","code":"speed(0)\nhideturtle()\ndef disc(x,y,r,c):\n    penup()\n    goto(x,y)\n    dot(2*r,c)\ndef path(points,c,w=3):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    pensize(w)\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    penup()\ndef fill(points,c):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    begin_fill()\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    goto(points[0][0],points[0][1])\n    end_fill()\n    penup()\ndef rect(x,y,w,h,c):\n    fill([(x,y),(x+w,y),(x+w,y+h),(x,y+h)],c)\nbgcolor(\"#f6f1e8\")\ndef carpet(x,y,size,level):\n    if level==0:\n        rect(x,y,size,size,\"#42878c\")\n        return\n    s=size/3\n    for row in range(3):\n        for col in range(3):\n            if row!=1 or col!=1:\n                carpet(x+col*s,y+row*s,s,level-1)\ncarpet(-162,-162,324,3)\nhideturtle()","art":"curated"},{"id":"curatedF28","title":"Julia Set","category":"Math","desc":"A mathematical complex-plane Julia fractal","code":"speed(0)\nhideturtle()\ndef disc(x,y,r,c):\n    penup()\n    goto(x,y)\n    dot(2*r,c)\ndef path(points,c,w=3):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    pensize(w)\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    penup()\ndef fill(points,c):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    begin_fill()\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    goto(points[0][0],points[0][1])\n    end_fill()\n    penup()\ndef rect(x,y,w,h,c):\n    fill([(x,y),(x+w,y),(x+w,y+h),(x,y+h)],c)\nbgcolor(\"#112d40\")\nfor row in range(68):\n    for col in range(68):\n        x=(col-34)/22\n        y=(row-34)/22\n        zx,zy=x,y\n        count=0\n        for k in range(17):\n            xx=zx*zx-zy*zy-.7\n            zy=2*zx*zy+.27015\n            zx=xx\n            if zx*zx+zy*zy>16:\n                break\n            count+=1\n        if count>3:\n            disc((col-34)*5.2,(row-34)*5.2,2.7,\n                 [\"#68a6b8\",\"#b2a3ce\",\"#f2bf7e\",\"#7ec4b5\"][count%4])\nhideturtle()","art":"curated"},{"id":"curatedF29","title":"Mandelbrot Set","category":"Math","desc":"An escape-time rendering of the Mandelbrot fractal","code":"speed(0)\nhideturtle()\ndef disc(x,y,r,c):\n    penup()\n    goto(x,y)\n    dot(2*r,c)\ndef path(points,c,w=3):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    pensize(w)\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    penup()\ndef fill(points,c):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    begin_fill()\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    goto(points[0][0],points[0][1])\n    end_fill()\n    penup()\ndef rect(x,y,w,h,c):\n    fill([(x,y),(x+w,y),(x+w,y+h),(x,y+h)],c)\nbgcolor(\"#122a3c\")\nfor row in range(65):\n    for col in range(83):\n        cx=-2.2+col*.036\n        cy=-1.2+row*.038\n        zx,zy=0,0\n        count=0\n        for k in range(17):\n            xx=zx*zx-zy*zy+cx\n            zy=2*zx*zy+cy\n            zx=xx\n            if zx*zx+zy*zy>16:\n                break\n            count+=1\n        if count>=6:\n            disc((col-41)*4.4,(row-32)*5.4,2.6,\n                 [\"#66aec4\",\"#7ec0b2\",\"#ad99c6\",\"#edc47e\"][count%4])\nhideturtle()","art":"curated"},{"id":"curatedF30","title":"Parametric Heart","category":"Math","desc":"A heart traced using parametric equations","code":"speed(0)\nhideturtle()\ndef disc(x,y,r,c):\n    penup()\n    goto(x,y)\n    dot(2*r,c)\ndef path(points,c,w=3):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    pensize(w)\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    penup()\ndef fill(points,c):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    begin_fill()\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    goto(points[0][0],points[0][1])\n    end_fill()\n    penup()\ndef rect(x,y,w,h,c):\n    fill([(x,y),(x+w,y),(x+w,y+h),(x,y+h)],c)\nimport math\nbgcolor(\"#f8eee9\")\npenup()\ncolor(\"#d36579\")\npensize(5)\nfor n in range(1300):\n    t=n*math.pi*2/1299\n    x=10*16*math.sin(t)**3\n    y=10*(13*math.cos(t)-5*math.cos(2*t)-2*math.cos(3*t)-math.cos(4*t))\n    goto(x,y)\n    pendown()\nhideturtle()","art":"curated"},{"id":"curatedF31","title":"Butterfly Curve","category":"Math","desc":"An intricate butterfly curve from polar equations","code":"speed(0)\nhideturtle()\ndef disc(x,y,r,c):\n    penup()\n    goto(x,y)\n    dot(2*r,c)\ndef path(points,c,w=3):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    pensize(w)\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    penup()\ndef fill(points,c):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    begin_fill()\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    goto(points[0][0],points[0][1])\n    end_fill()\n    penup()\ndef rect(x,y,w,h,c):\n    fill([(x,y),(x+w,y),(x+w,y+h),(x,y+h)],c)\nimport math\nbgcolor(\"#132a3d\")\npenup()\npensize(2)\ncolors=[\"#e7ac89\",\"#9cc0ae\",\"#b99fc9\",\"#efc776\"]\nfor n in range(2100):\n    t=n*12*math.pi/2099\n    r=math.exp(math.cos(t))-2*math.cos(4*t)+math.sin(t/12)**5\n    x=40*r*math.sin(t)\n    y=40*r*math.cos(t)\n    color(colors[(n//160)%4])\n    goto(x,y)\n    pendown()\nhideturtle()","art":"curated"},{"id":"curatedF32","title":"Lissajous Knot","category":"Math","desc":"A closed curve governed by two sine oscillations","code":"speed(0)\nhideturtle()\ndef disc(x,y,r,c):\n    penup()\n    goto(x,y)\n    dot(2*r,c)\ndef path(points,c,w=3):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    pensize(w)\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    penup()\ndef fill(points,c):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    begin_fill()\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    goto(points[0][0],points[0][1])\n    end_fill()\n    penup()\ndef rect(x,y,w,h,c):\n    fill([(x,y),(x+w,y),(x+w,y+h),(x,y+h)],c)\nimport math\nbgcolor(\"#fbf5e8\")\npenup()\ncolor(\"#5e96a5\")\npensize(3)\nfor n in range(1800):\n    t=2*math.pi*n/1799\n    x=152*math.sin(3*t+.7)\n    y=134*math.sin(4*t)\n    goto(x,y)\n    pendown()\ndisc(0,0,9,\"#e9ba7c\")\nhideturtle()","art":"curated"},{"id":"curatedF33","title":"Hypotrochoid","category":"Math","desc":"A rolling circle traced inside a larger circle","code":"speed(0)\nhideturtle()\ndef disc(x,y,r,c):\n    penup()\n    goto(x,y)\n    dot(2*r,c)\ndef path(points,c,w=3):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    pensize(w)\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    penup()\ndef fill(points,c):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    begin_fill()\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    goto(points[0][0],points[0][1])\n    end_fill()\n    penup()\ndef rect(x,y,w,h,c):\n    fill([(x,y),(x+w,y),(x+w,y+h),(x,y+h)],c)\nimport math\nbgcolor(\"#142c3b\")\npenup()\ncolors=[\"#7fc4b3\",\"#e7b776\",\"#c69dbe\"]\npensize(2)\nR,r,d=115,41,77\nfor n in range(1900):\n    t=15*math.pi*n/1899\n    x=(R-r)*math.cos(t)+d*math.cos((R-r)*t/r)\n    y=(R-r)*math.sin(t)-d*math.sin((R-r)*t/r)\n    color(colors[(n//160)%3])\n    goto(x,y)\n    pendown()\nhideturtle()","art":"curated"},{"id":"curatedF34","title":"Epitrochoid","category":"Math","desc":"An orbiting point tracing loops outside a circle","code":"speed(0)\nhideturtle()\ndef disc(x,y,r,c):\n    penup()\n    goto(x,y)\n    dot(2*r,c)\ndef path(points,c,w=3):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    pensize(w)\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    penup()\ndef fill(points,c):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    begin_fill()\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    goto(points[0][0],points[0][1])\n    end_fill()\n    penup()\ndef rect(x,y,w,h,c):\n    fill([(x,y),(x+w,y),(x+w,y+h),(x,y+h)],c)\nimport math\nbgcolor(\"#f8f4e8\")\npenup()\npensize(2)\ncolors=[\"#d88473\",\"#779cab\",\"#9e9aba\"]\nR,r,d=62,23,43\nfor n in range(1800):\n    t=16*math.pi*n/1799\n    x=(R+r)*math.cos(t)-d*math.cos((R+r)*t/r)\n    y=(R+r)*math.sin(t)-d*math.sin((R+r)*t/r)\n    color(colors[(n//200)%3])\n    goto(x,y)\n    pendown()\nhideturtle()","art":"curated"},{"id":"curatedF35","title":"Guilloché Engraving","category":"Art","desc":"Fine overlapping curves resembling security engraving","code":"speed(0)\nhideturtle()\ndef disc(x,y,r,c):\n    penup()\n    goto(x,y)\n    dot(2*r,c)\ndef path(points,c,w=3):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    pensize(w)\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    penup()\ndef fill(points,c):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    begin_fill()\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    goto(points[0][0],points[0][1])\n    end_fill()\n    penup()\ndef rect(x,y,w,h,c):\n    fill([(x,y),(x+w,y),(x+w,y+h),(x,y+h)],c)\nimport math\nbgcolor(\"#f8f4eb\")\nfor layer in range(4):\n    penup()\n    color([\"#5b9299\",\"#d4a477\",\"#a38bb9\",\"#7cb5a4\"][layer])\n    pensize(1.4)\n    for n in range(1100):\n        t=2*math.pi*n/1099\n        r=90+18*math.cos((12+layer)*t)+10*math.sin((17+layer)*t)\n        x=r*math.cos(t+layer*.13)\n        y=r*math.sin(t+layer*.13)\n        goto(x,y)\n        pendown()\nhideturtle()","art":"curated"},{"id":"curatedF36","title":"Logarithmic Spiral","category":"Math","desc":"A spiral that grows exponentially with its angle","code":"speed(0)\nhideturtle()\ndef disc(x,y,r,c):\n    penup()\n    goto(x,y)\n    dot(2*r,c)\ndef path(points,c,w=3):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    pensize(w)\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    penup()\ndef fill(points,c):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    begin_fill()\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    goto(points[0][0],points[0][1])\n    end_fill()\n    penup()\ndef rect(x,y,w,h,c):\n    fill([(x,y),(x+w,y),(x+w,y+h),(x,y+h)],c)\nimport math\nbgcolor(\"#172e40\")\npenup()\npensize(3)\nfor n in range(1600):\n    t=n*5*math.pi/1599\n    r=4*math.exp(t*.225)\n    x=r*math.cos(t)\n    y=r*math.sin(t)\n    color(\"#75cbb7\" if n%2 else \"#d9b979\")\n    goto(x,y)\n    pendown()\nhideturtle()","art":"curated"},{"id":"curatedF37","title":"Wireframe Torus","category":"Math","desc":"A torus projected from three-dimensional coordinates","code":"speed(0)\nhideturtle()\ndef disc(x,y,r,c):\n    penup()\n    goto(x,y)\n    dot(2*r,c)\ndef path(points,c,w=3):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    pensize(w)\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    penup()\ndef fill(points,c):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    begin_fill()\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    goto(points[0][0],points[0][1])\n    end_fill()\n    penup()\ndef rect(x,y,w,h,c):\n    fill([(x,y),(x+w,y),(x+w,y+h),(x,y+h)],c)\nimport math\nbgcolor(\"#182c3e\")\nR,r=95,46\nfor ring in range(0,360,15):\n    penup()\n    color(\"#78c3bd\" if ring%30 else \"#e1b87f\")\n    pensize(1.8)\n    for n in range(101):\n        t=n*2*math.pi/100\n        p=math.radians(ring)\n        x=(R+r*math.cos(p))*math.cos(t)\n        y=(R+r*math.cos(p))*math.sin(t)*.52+r*math.sin(p)*.62\n        goto(x,y)\n        pendown()\nhideturtle()","art":"curated"},{"id":"curatedF38","title":"Globe Latitudes","category":"Science","desc":"A globe with visible longitude and latitude lines","code":"speed(0)\nhideturtle()\ndef disc(x,y,r,c):\n    penup()\n    goto(x,y)\n    dot(2*r,c)\ndef path(points,c,w=3):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    pensize(w)\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    penup()\ndef fill(points,c):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    begin_fill()\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    goto(points[0][0],points[0][1])\n    end_fill()\n    penup()\ndef rect(x,y,w,h,c):\n    fill([(x,y),(x+w,y),(x+w,y+h),(x,y+h)],c)\nimport math\nbgcolor(\"#f4f3e9\")\ndisc(0,0,149,\"#b8d4d6\")\nfor lat in [-60,-30,0,30,60]:\n    penup()\n    color(\"#5b99a1\")\n    pensize(2)\n    y=149*math.sin(math.radians(lat))\n    r=149*math.cos(math.radians(lat))\n    for n in range(121):\n        t=n*math.pi/60\n        goto(r*math.cos(t),y+r*.22*math.sin(t))\n        pendown()\nfor lon in range(-75,76,30):\n    penup()\n    color(\"#5b99a1\")\n    for n in range(121):\n        t=-math.pi/2+n*math.pi/120\n        goto(149*math.sin(math.radians(lon))*math.cos(t),\n             149*math.sin(t))\n        pendown()\nhideturtle()","art":"curated"},{"id":"curatedF39","title":"Wire Sphere","category":"Math","desc":"A 3D wire sphere projected as curved great circles","code":"speed(0)\nhideturtle()\ndef disc(x,y,r,c):\n    penup()\n    goto(x,y)\n    dot(2*r,c)\ndef path(points,c,w=3):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    pensize(w)\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    penup()\ndef fill(points,c):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    begin_fill()\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    goto(points[0][0],points[0][1])\n    end_fill()\n    penup()\ndef rect(x,y,w,h,c):\n    fill([(x,y),(x+w,y),(x+w,y+h),(x,y+h)],c)\nimport math\nbgcolor(\"#182e42\")\nfor phi in range(0,180,15):\n    penup()\n    color(\"#77b7b9\" if phi%30 else \"#e6bd88\")\n    pensize(1.5)\n    for n in range(181):\n        t=n*2*math.pi/180\n        a=math.radians(phi)\n        x=143*(math.cos(t)*math.cos(a))\n        y=143*(math.sin(t)*.72+math.cos(t)*math.sin(a)*.28)\n        goto(x,y)\n        pendown()\nhideturtle()","art":"curated"},{"id":"curatedF40","title":"Perspective Highway","category":"Art","desc":"A straight highway narrowing toward a distant vanishing point","code":"speed(0)\nhideturtle()\ndef disc(x,y,r,c):\n    penup()\n    goto(x,y)\n    dot(2*r,c)\ndef path(points,c,w=3):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    pensize(w)\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    penup()\ndef fill(points,c):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    begin_fill()\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    goto(points[0][0],points[0][1])\n    end_fill()\n    penup()\ndef rect(x,y,w,h,c):\n    fill([(x,y),(x+w,y),(x+w,y+h),(x,y+h)],c)\nbgcolor(\"#eac49b\")\ndisc(102,119,48,\"#f2dbad\")\nfill([(-200,-200),(-200,-61),(-93,-101),(33,-61),(200,-102),(200,-200)],\"#bca588\")\nfill([(-185,-200),(185,-200),(20,5),(-20,5)],\"#596b71\")\nfor x in [-1,1]:\n    path([(x*112,-200),(x*8,5)],\"#efe2c1\",5)\nfor y,w in [(-180,40),(-129,25),(-74,13),(-29,6)]:\n    rect(-w/2,y,w,13,\"#e7c47f\")\nhideturtle()","art":"curated"},{"id":"curatedF41","title":"One-Point Perspective","category":"Art","desc":"A tiled hallway converging toward one central point","code":"speed(0)\nhideturtle()\ndef disc(x,y,r,c):\n    penup()\n    goto(x,y)\n    dot(2*r,c)\ndef path(points,c,w=3):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    pensize(w)\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    penup()\ndef fill(points,c):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    begin_fill()\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    goto(points[0][0],points[0][1])\n    end_fill()\n    penup()\ndef rect(x,y,w,h,c):\n    fill([(x,y),(x+w,y),(x+w,y+h),(x,y+h)],c)\nbgcolor(\"#e9e5dc\")\npath([(-193,-176),(0,25),(193,-176)],\"#6e939b\",3)\npath([(-193,173),(0,25),(193,173)],\"#6e939b\",3)\nfor x in [-156,-102,-49,49,102,156]:\n    path([(x,-176),(0,25)],\"#a3bab7\",2)\n    path([(x,173),(0,25)],\"#a3bab7\",2)\nfor y in [-146,-93,-45,83,123,161]:\n    path([(-184,y),(184,y)],\"#bbbfaf\",2)\nrect(-29,-21,58,91,\"#4f727c\")\ndisc(0,12,9,\"#d4ba82\")\nhideturtle()","art":"curated"},{"id":"curatedF42","title":"Optical Moiré","category":"Art","desc":"Two overlaid curved line fields create a moiré pattern","code":"speed(0)\nhideturtle()\ndef disc(x,y,r,c):\n    penup()\n    goto(x,y)\n    dot(2*r,c)\ndef path(points,c,w=3):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    pensize(w)\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    penup()\ndef fill(points,c):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    begin_fill()\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    goto(points[0][0],points[0][1])\n    end_fill()\n    penup()\ndef rect(x,y,w,h,c):\n    fill([(x,y),(x+w,y),(x+w,y+h),(x,y+h)],c)\nimport math\nbgcolor(\"#f4f1e7\")\nfor layer in range(2):\n    for line in range(-130,131,13):\n        penup()\n        color(\"#3b7884\" if layer==0 else \"#ca8b77\")\n        pensize(1.2)\n        for x in range(-172,173,4):\n            y=line+math.sin(x/29+layer*.4)*13+layer*6\n            goto(x,y)\n            pendown()\nhideturtle()","art":"curated"},{"id":"curatedF43","title":"Wave Interference","category":"Math","desc":"Two circular wave sources produce overlapping ripples","code":"speed(0)\nhideturtle()\ndef disc(x,y,r,c):\n    penup()\n    goto(x,y)\n    dot(2*r,c)\ndef path(points,c,w=3):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    pensize(w)\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    penup()\ndef fill(points,c):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    begin_fill()\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    goto(points[0][0],points[0][1])\n    end_fill()\n    penup()\ndef rect(x,y,w,h,c):\n    fill([(x,y),(x+w,y),(x+w,y+h),(x,y+h)],c)\nbgcolor(\"#183144\")\nfor cx,shade in [(-46,\"#72bfc0\"),(46,\"#e4b87d\")]:\n    for r in range(14,181,17):\n        penup()\n        goto(cx,-r)\n        setheading(0)\n        color(shade)\n        pensize(1.7)\n        pendown()\n        circle(r)\nfor cx in [-46,46]:\n    disc(cx,0,8,\"#f7ebca\")\nhideturtle()","art":"curated"},{"id":"curatedF44","title":"Recursive Sunburst","category":"Math","desc":"Recursive rays splitting into finer branches","code":"speed(0)\nhideturtle()\ndef disc(x,y,r,c):\n    penup()\n    goto(x,y)\n    dot(2*r,c)\ndef path(points,c,w=3):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    pensize(w)\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    penup()\ndef fill(points,c):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    begin_fill()\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    goto(points[0][0],points[0][1])\n    end_fill()\n    penup()\ndef rect(x,y,w,h,c):\n    fill([(x,y),(x+w,y),(x+w,y+h),(x,y+h)],c)\nbgcolor(\"#f8f2e6\")\ndef ray(length,depth):\n    if depth==0:\n        dot(5,\"#d6a06d\")\n        return\n    forward(length)\n    left(27)\n    ray(length*.5,depth-1)\n    right(54)\n    ray(length*.5,depth-1)\n    left(27)\n    backward(length)\nfor i in range(12):\n    penup()\n    goto(0,0)\n    setheading(i*30)\n    color(\"#ca8f6e\")\n    pensize(2)\n    pendown()\n    ray(36,3)\nhideturtle()","art":"curated"},{"id":"curatedF45","title":"Voronoi Diagram","category":"Math","desc":"Colored regions nearest to a set of seed points","code":"speed(0)\nhideturtle()\ndef disc(x,y,r,c):\n    penup()\n    goto(x,y)\n    dot(2*r,c)\ndef path(points,c,w=3):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    pensize(w)\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    penup()\ndef fill(points,c):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    begin_fill()\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    goto(points[0][0],points[0][1])\n    end_fill()\n    penup()\ndef rect(x,y,w,h,c):\n    fill([(x,y),(x+w,y),(x+w,y+h),(x,y+h)],c)\nbgcolor(\"#f7f3eb\")\nseeds=[(-120,-92),(-95,112),(31,-137),(112,-58),(116,108),(-5,27)]\ncolors=[\"#96bfbb\",\"#d7a187\",\"#b0aad0\",\"#ddbe83\",\"#80a1bc\",\"#b7c898\"]\nfor y in range(-178,179,11):\n    for x in range(-178,179,11):\n        nearest=0\n        best=1000000\n        for i,(sx,sy) in enumerate(seeds):\n            d=(x-sx)**2+(y-sy)**2\n            if d<best:\n                best=d\n                nearest=i\n        disc(x,y,6,colors[nearest])\nfor x,y in seeds:\n    disc(x,y,8,\"#435b63\")\nhideturtle()","art":"curated"},{"id":"curatedF46","title":"Connected Web","category":"Math","desc":"A network of rings connected by short curved links","code":"speed(0)\nhideturtle()\ndef disc(x,y,r,c):\n    penup()\n    goto(x,y)\n    dot(2*r,c)\ndef path(points,c,w=3):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    pensize(w)\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    penup()\ndef fill(points,c):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    begin_fill()\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    goto(points[0][0],points[0][1])\n    end_fill()\n    penup()\ndef rect(x,y,w,h,c):\n    fill([(x,y),(x+w,y),(x+w,y+h),(x,y+h)],c)\nimport math\nbgcolor(\"#102b3c\")\npoints=[]\nfor i in range(24):\n    a=i*2*math.pi/24\n    r=135+16*math.sin(i*7)\n    points.append((r*math.cos(a),r*math.sin(a)))\nfor i in range(24):\n    for delta in [1,5,9]:\n        path([points[i],points[(i+delta)%24]],\n             \"#679eab\" if delta==1 else \"#8c8bb0\",1)\nfor i,(x,y) in enumerate(points):\n    disc(x,y,6,\"#edc37d\" if i%3==0 else \"#83bdc0\")\nhideturtle()","art":"curated"},{"id":"curatedF47","title":"Procedural Terrain","category":"Math","desc":"A layered landscape generated from overlapping wave functions","code":"speed(0)\nhideturtle()\ndef disc(x,y,r,c):\n    penup()\n    goto(x,y)\n    dot(2*r,c)\ndef path(points,c,w=3):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    pensize(w)\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    penup()\ndef fill(points,c):\n    penup()\n    goto(points[0][0],points[0][1])\n    color(c)\n    begin_fill()\n    pendown()\n    for x,y in points[1:]:\n        goto(x,y)\n    goto(points[0][0],points[0][1])\n    end_fill()\n    penup()\ndef rect(x,y,w,h,c):\n    fill([(x,y),(x+w,y),(x+w,y+h),(x,y+h)],c)\nimport math\nbgcolor(\"#f0d5b6\")\ncolors=[\"#c8a2a0\",\"#a18f9b\",\"#77879a\",\"#4d7887\",\"#356675\"]\nfor layer in range(5):\n    pts=[(-200,-200)]\n    for x in range(-200,201,5):\n        y=95-layer*51+math.sin(x/31+layer*.8)*19\n        y+=math.sin(x/13+layer*3)*8\n        pts.append((x,y))\n    pts.append((200,-200))\n    fill(pts,colors[layer])\ndisc(127,137,35,\"#f6e4b6\")\nhideturtle()","art":"curated"}]);
